1\u043d\u0438\u0436\u0430\u0435\u0442 \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0438\u00bb.\n\n## 2. \u041f\u043e\u043b\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d\n\n**2.1 \u0412\u0435\u0442\u043a\u0438**\n\n| \u0412\u0435\u0442\u043a\u0430 | \u041e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 | Feedback |\n|---|---|---|\n| **A. Baseline** | \u0427\u0438\u0441\u0442\u0430\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u0438\u0437 \u043e\u0431\u0443\u0447\u0435\u043d\u043d\u043e\u0433\u043e \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430 (arg max/\u0442\u0435\u043c\u043f\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0441\u044d\u043c\u043f\u043b\u0438\u043d\u0433), \u0431\u0435\u0437 \u0432\u043d\u0435\u0448\u043d\u0435\u0433\u043e \u0441\u0438\u0433\u043d\u0430\u043b\u0430 \u0441\u0432\u043e\u0439\u0441\u0442\u0432 | \u043d\u0435\u0442 |\n| **B. Reward-RL feedback (\u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f)** | \u0422\u043e\u0442 \u0436\u0435 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440, \u0434\u043e\u043e\u0431\u0443\u0447\u0435\u043d\u043d\u044b\u0439/\u0441\u044d\u043c\u043f\u043b\u0438\u0440\u0443\u0435\u043c\u044b\u0439 \u0441\u043e \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u043c reward-\u0446\u0438\u043a\u043b\u043e\u043c REINVENT-style (\u0441\u043c. \u043f.3) | \u0434\u0430 |\n| **C. Classifier-guided (\u0430\u0431\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0440\u0443\u043a\u0430\u0432, \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e)** | \u0422\u043e\u0442 \u0436\u0435 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 + \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 \u00ab\u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0435/\u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435\u00bb, \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0439 \u0441\u044d\u043c\u043f\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435; \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0431\u044e\u0434\u0436\u0435\u0442 | \u0434\u0430 (\u0434\u0440\u0443\u0433\u0430\u044f \u0444\u043e\u0440\u043c\u0430) |\n\n**2.2 \u0423\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u043c\u044b\u0435/\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435** (\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b \u0434\u043b\u044f A, B \u0438 C):\n- \u043e\u0431\u0443\u0447\u0430\u044e\u0449\u0438\u0439/\u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u0439 \u043a\u043e\u0440\u043f\u0443\u0441 (\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439, \u0442\u043e\u0442 \u0436\u0435 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0432\u0435\u0442\u043e\u043a);\n- \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430, \u0440\u0430\u0437\u043c\u0435\u0440\u044b, \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440, \u0447\u0438\u0441\u043b\u043e \u044d\u043f\u043e\u0445 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f;\n- \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 \u0441\u044d\u043c\u043f\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f (\u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u0430 T \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0430), \u0447\u0438\u0441\u043b\u043e \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u043c\u044b\u0445 \u043c\u043e\u043b\u0435\u043a\u0443\u043b N \u043d\u0430 \u043f\u0440\u043e\u0433\u043e\u043d;\n- seed \u043d\u0430 \u043f\u0430\u0440\u0443 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 (\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0434\u043b\u044f A \u0438 B \u0432 \u043e\u0434\u043d\u043e\u0439 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u0438);\n- \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0441\u0440\u0435\u0434\u0430 \u0438 \u0432\u0435\u0440\u0441\u0438\u0438 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0432 \u043c\u0430\u043d\u0438\u0444\u0435\u0441\u0442\u0435 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f).\n\n**2.3 \u041f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u0438 \u0438 \u0440\u0430\u043d\u0434\u043e\u043c\u0438\u0437\u0430\u0446\u0438\u044f.** M = 8 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0445 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 (\u0440\u0430\u0437\u043d\u044b\u0435 seed; 5 \u2014 \u043c\u0438\u043d\u0438\u043c\u0443\u043c, 8 \u2014 \u0446\u0435\u043b\u0435\u0432\u043e\u0435). \u041a\u0430\u0436\u0434\u044b\u0439 \u043f\u0440\u043e\u0433\u043e\u043d: \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435 \u0431\u0430\u0437\u043e\u0432\u043e\u0433\u043e \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u2192 \u0441\u044d\u043c\u043f\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0432\u0435\u0442\u043a\u0438 A (N = 10 000 \u043c\u043e\u043b\u0435\u043a\u0443\u043b) \u0438 \u0432\u0435\u0442\u043a\u0438 B (N = 10 000) \u043d\u0430 \u0442\u043e\u043c \u0436\u0435 \u0434\u0430\u043d\u043d\u044b\u0445/seed \u2192 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0435 \u0432\u0441\u0435\u0445 \u043c\u0435\u0442\u0440\u0438\u043a. \u0412\u0435\u0442\u043a\u0430 C \u2014 \u0442\u0435 \u0436\u0435 M \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 (\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e). \u041f\u043e\u0440\u044f\u0434\u043e\u043a \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f seed-\u0442\u0430\u0431\u043b\u0438\u0446\u0435\u0439 \u0437\u0430\u0440\u0430\u043d\u0435\u0435.\n\n## 3. Baseline \u0438 \u0444\u043e\u0440\u043c\u0430 feedback: \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435 \u0438 \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u044b\n\n**\u0411\u0430\u0437\u043e\u0432\u0430\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c (\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 \u043e \u0432\u044b\u0431\u043e\u0440\u0435):** SMILES-\u0431\u0430\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 character-level RNN (GRU/LSTM) \u043a\u0430\u043a \u0432 REINVENT, \u043b\u0438\u0431\u043e \u043c\u0430\u043b\u044b\u0439 transformer-\u0434\u0435\u043a\u043e\u0434\u0435\u0440. \u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435: (i) \u044d\u0442\u043e \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0439, \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u044b\u0439, \u043b\u0451\u0433\u043a\u0438\u0439 \u0432 CPU-\u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0438 \u043a\u043b\u0430\u0441\u0441; (ii) \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430 \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 RL-\u0444\u0438\u043d\u0442\u044e\u043d\u0430 \u0441 \u043f\u043e\u0434\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0438\u0435\u043c (REINVENT-\u043a\u043b\u0430\u0441\u0441), \u0447\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u0432\u0435\u0442\u043a\u0443 B \u0447\u0435\u0441\u0442\u043d\u044b\u043c \u00ab\u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043e\u0431\u0430\u0432\u0438\u043b\u0438 \u0446\u0438\u043a\u043b\u00bb-\u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435\u043c; (iii) \u043f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u043c \u043d\u0430 \u043f\u0440\u0435\u0434\u043e\u0431\u0443\u0447\u0435\u043d\u043d\u044b\u0439 big-model \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0432\u0435\u0442\u043a\u0435 C-\u043e\u0431\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439. \u0410\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u044b (\u043e\u0442\u043c\u0435\u0442\u0430\u0435\u043c \u043a\u0430\u043a \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435, \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u0443\u0435\u043c): VAE/Junction-Tree VAE (\u0434\u0440\u0443\u0433\u043e\u0435 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u043e\u0435 \u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0441\u0442\u0432\u043e), diffusion \u043f\u043e \u0433\u0440\u0430\u0444\u0430\u043c (\u0441\u043b\u043e\u0436\u043d\u0435\u0435 RL-\u0444\u0438\u043d\u0442\u044e\u043d, \u0434\u043e\u0440\u043e\u0436\u0435 \u043d\u0430 CPU), GPT-\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0435 \u0431\u043e\u043b\u044c\u0448\u0438\u0435 \u0442\u0440\u0430\u043d\u0441\u0444\u043e\u0440\u043c\u0435\u0440\u044b (\u0438\u0437\u0431\u044b\u0442\u043e\u0447\u043d\u044b \u0438 \u043d\u0435 \u043d\u0443\u0436\u043d\u044b \u043f\u0440\u0438 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 \u00ab\u043e\u0434\u043d\u0430 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f\u00bb).\n\n**\u041e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u0444\u043e\u0440\u043c\u0430 feedback (\u0432\u0435\u0442\u043a\u0430 B, \u043b\u043e\u043a-\u0438\u043d):** reward-based RL-\u0444\u0438\u043d\u0442\u044e\u043d \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430, REINVENT-style \u2014 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435 \u0441 **augmented likelihood**, \u0433\u0434\u0435 policy-\u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0438\u0440\u0443\u0435\u0442 log P(\u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430) \u0441 \u0434\u043e\u0431\u0430\u0432\u043a\u043e\u0439 reward-\u0442\u0435\u0440\u043c\u0430:\nloss = \u2212( log P(x) + \u03c3\u00b7R(x) ) \u2192 \u043c\u0438\u043d\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u044f, \u0433\u0434\u0435 \u03c3 \u2014 \u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u043d\u044b\u0439 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 reward (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u03c3 \u2208 {10, 20, 50} \u043a\u0430\u043a sensitivity-\u0440\u0430\u0437\u0432\u0451\u0440\u0442\u043a\u0430), \u0430 \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u0434\u0435\u043b\u0430\u044e\u0442\u0441\u044f \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u044f\u043c\u0438 \u043f\u043e \u0431\u0430\u0442\u0447\u0430\u043c \u0441\u044d\u043c\u043f\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043c\u043e\u043b\u0435\u043a\u0443\u043b. \u0421\u044d\u043c\u043f\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435/\u0438\u043d\u0442\u0435\u0440\u043f\u043e\u043b\u044f\u0446\u0438\u044f reward: reward-\u0442\u0435\u0440\u043c \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0432\u0437\u0432\u0435\u0448\u0435\u043d\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u044f, **\u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043a [0,1]** \u043f\u043e \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430\u043c \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f:\n- R_prop = \u03bb1\u00b7clamp01( (p-logP \u2212 pmin*)/(p* \u2212 pmin*) ) + \u03bb2\u00b7QED / QED_max, \u0433\u0434\u0435 p* \u2014 \u0446\u0435\u043b\u0435\u0432\u0430\u044f \u044f\u0447\u0435\u0439\u043a\u0430 p-logP (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, [1.0, 4.0] \u2014 \u043b\u0438\u043f\u043e\u0444\u0438\u043b\u044c\u043d\u044b\u0439 \u00abdrug-like\u00bb \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d), pmin* \u2014 \u043d\u0438\u0436\u043d\u044f\u044f \u0433\u0440\u0430\u043d\u0438\u0446\u0430. \u0412\u0435\u0441\u0430 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u03bb1 = 0.6, \u03bb2 = 0.4 (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c; sensitivity \u043f\u043e \u03bb).\n- R_shape = \u2212penalty(\u043d\u0435\u0440\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c/\u0443\u043b\u044c\u0442\u0440\u0430-\u0434\u043b\u0438\u043d\u043d\u044b\u0435 \u0446\u0435\u043f\u043e\u0447\u043a\u0438): \u0448\u0442\u0440\u0430\u0444 = f(\u0434\u043b\u0438\u043d\u0430 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0439 \u043b\u0438\u043d\u0435\u0439\u043d\u043e\u0439 sp3-\u0446\u0435\u043f\u0438, SAScore, \u0434\u043e\u043b\u044f \u043d\u0435\u0440\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u043d\u044b\u0445 \u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0435\u0439). \u0414\u043b\u044f \u0441\u0432\u0435\u0440\u0445\u0434\u043b\u0438\u043d\u043d\u044b\u0445 \u0446\u0435\u043f\u0435\u0439 \u2014 soft-\u0448\u0442\u0440\u0430\u0444, \u043b\u0438\u043d\u0435\u0439\u043d\u043e \u0440\u0430\u0441\u0442\u0443\u0449\u0438\u0439 \u0432\u044b\u0448\u0435 \u043f\u043e\u0440\u043e\u0433\u0430 L* (\u0441\u043c. \u043f.4), \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 penalty = max(0, (L \u2212 L*)/L*)\u00b7c; \u0438\u043d\u0430\u0447\u0435 \u00ab\u0443\u0433\u043e\u043b\u00bb \u0444\u0443\u043d\u043a\u0446\u0438\u0438 \u043f\u043b\u043e\u0441\u043a\u0438\u0439, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u0441\u043c\u0435\u0449\u0430\u0442\u044c \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0446\u0435\u043b\u0438\u043a\u043e\u043c \u043a \u043f\u0440\u0435\u0434\u0435\u043b\u044c\u043d\u043e \u043b\u0438\u043f\u043e\u0444\u0438\u043b\u044c\u043d\u044b\u043c \u043c\u0430\u043b\u044b\u043c \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430\u043c.\n- **\u0418\u0442\u043e\u0433\u043e\u0432\u044b\u0439 reward:** R(x) = w1\u00b7R_prop + w2\u00b7R_shape, w1 = 0.5, w2 = 0.5 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e (\u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043f\u043e w2 \u2208 {0.3, 0.5, 0.7}). Reward \u0438\u043d\u0442\u0435\u0440\u043f\u043e\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u043e \u0445\u043e\u0434\u0443 \u0446\u0438\u043a\u043b\u0430 (\u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0439 warm-up reward over first K \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439 \u0444\u0438\u043d\u0442\u044e\u043d\u0430), reward-\u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0441\u043a\u043e\u043b\u044c\u0437\u044f\u0449\u0435\u0439 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u043e\u0439 \u043f\u043e \u0431\u0430\u0442\u0447\u0443. \u041a\u043b\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u00abREINVENT\u00bb-\u0441\u0442\u0438\u043b\u044c: augmented likelihood \u043e\u0442\u0441\u0435\u043a\u0430\u0435\u0442 \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0431\u044b\u0441\u0442\u0440\u044b\u0439 \u0443\u0445\u043e\u0434 \u043e\u0442 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u043c\u043e\u0434\u0435\u043b\u0438 (KL-\u0440\u0435\u0433\u0443\u043b\u044f\u0440\u0438\u0437\u0430\u0446\u0438\u044f \u043a \u0431\u0430\u0437\u043e\u0432\u043e\u043c\u0443 policy).\n- **\u0426\u0438\u043a\u043b \u043e\u0431\u0440\u0430\u0442\u043d\u043e\u0439 \u0441\u0432\u044f\u0437\u0438 \u00ab\u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439\u00bb:** \u0432 \u043a\u0430\u0436\u0434\u043e\u0439 RL-\u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0438 \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0431\u0430\u0442\u0447 \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u2192 RDKit \u0432\u044b\u0447\u0438\u0441\u043b\u044f\u0435\u0442 p-logP/QED \u0438 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u044b\u0435 \u0448\u0442\u0440\u0430\u0444\u044b \u2192 reward \u2192 policy-\u0433\u0440\u0430\u0434\u0438\u0435\u043d\u0442/\u043f\u043e\u0434\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0438\u0435 \u2192 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u0431\u0430\u0442\u0447. \u0422.\u0435. \u0441\u0438\u0433\u043d\u0430\u043b \u0441\u0432\u043e\u0439\u0441\u0442\u0432 \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u0441\u0430\u043c\u043e \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435, \u0430 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u043f\u043e\u0441\u0442\u0444\u0438\u043b\u044c\u0442\u0440\u0430\u0446\u0438\u044e (\u0432 \u043e\u0442\u043b\u0438\u0447\u0438\u0435 \u043e\u0442 baseline, \u0433\u0434\u0435 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430 \u043d\u0438\u043a\u0430\u043a \u043d\u0435 \u0432\u043b\u0438\u044f\u044e\u0442).\n\n**\u0410\u0431\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0440\u0443\u043a\u0430\u0432 C (classifier-guided, \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e):** \u043e\u0431\u0443\u0447\u0430\u0435\u0442\u0441\u044f \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u0439 \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, gradient boosting/\u043c\u0430\u043b\u044b\u0439 MLP \u043d\u0430 RDKit-\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u0430\u0445+ECFP) \u00ab\u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0435 (\u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u0439 \u043a\u043e\u0440\u043f\u0443\u0441) vs \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u043c\u043e\u0435 baseline\u00bb; \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0441\u044d\u043c\u043f\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u2014 reward = w3\u00b7log p(real|x). \u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 B vs C \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043d\u0430 \u00ab\u0444\u043e\u0440\u043c\u0430 feedback \u0432\u0430\u0436\u043d\u0430?\u00bb \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u043e. \u0412\u043a\u043b\u044e\u0447\u0430\u0435\u043c \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u043c \u0431\u044e\u0434\u0436\u0435\u0442\u0435 CPU-\u0432\u0440\u0435\u043c\u0435\u043d\u0438.\n\n## 4. \u041e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0439 \u0438 \u044d\u0442\u0430\u043b\u043e\u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f\n\n**\u00ab\u0413\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u044f\u00bb (\u043b\u043e\u043a-\u0438\u043d, \u0442\u0440\u0438 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0438, \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u043f\u043e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e):**\n1. **\u041d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0435:** SMILES \u043d\u0435 \u043f\u0430\u0440\u0441\u0438\u0442\u0441\u044f RDKit (\u0441\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043e\u0448\u0438\u0431\u043a\u0430/\u043d\u0435\u0440\u0430\u0437\u0440\u0435\u0448\u0438\u043c\u044b\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b \u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438, \u043d\u0435\u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u044b\u0435 \u0440\u0430\u0434\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0435 \u0430\u0442\u043e\u043c\u044b).\n2. **\u0421\u0432\u0435\u0440\u0445\u0434\u043b\u0438\u043d\u043d\u044b\u0435/\u043d\u0435\u0440\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u043d\u044b\u0435 \u0445\u0432\u043e\u0441\u0442\u044b:** \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u043b\u0438\u043d\u0435\u0439\u043d\u0430\u044f \u0443\u0433\u043b\u0435\u0440\u043e\u0434\u043d\u0430\u044f sp3-\u0446\u0435\u043f\u044c > \u043f\u043e\u0440\u043e\u0433\u0430 L* (\u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e L* = 20 \u043f\u043e\u0434\u0440\u044f\u0434 \u0438\u0434\u0443\u0449\u0438\u0445 sp3-\u0443\u0433\u043b\u0435\u0440\u043e\u0434\u043e\u0432 \u2014 \u00abultra-long carbon chain\u00bb \u0438\u0437 \u0432\u043e\u043f\u0440\u043e\u0441\u0430). \u041f\u043e\u0440\u043e\u0433 \u2014 \u043f\u0440\u0435\u0434\u043c\u0435\u0442 sensitivity (\u043f.6.3).\n3. **\u0412\u044b\u0431\u0440\u043e\u0441\u044b \u043f\u043e \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u0430\u043c \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u044d\u0442\u0430\u043b\u043e\u043d\u0430:** \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430 \u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u043c\u0438 \u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0430 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u043f\u043e \u22651 \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u043c\u0443 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u0443 (\u0434\u043b\u0438\u043d\u0430 \u0446\u0435\u043f\u0438, \u0447\u0438\u0441\u043b\u043e \u0430\u0442\u043e\u043c\u043e\u0432, \u0447\u0438\u0441\u043b\u043e \u043a\u043e\u043b\u0435\u0446, SAScore): \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0432\u043d\u0435 [0.5%, 99.5%] \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u0435\u0439 \u044d\u0442\u0430\u043b\u043e\u043d\u0430 \u043f\u043e \u0434\u043b\u0438\u043d\u0435 \u0446\u0435\u043f\u0438/\u0447\u0438\u0441\u043b\u0443 \u0430\u0442\u043e\u043c\u043e\u0432, \u0438\u043b\u0438 SAScore \u0432\u044b\u0448\u0435 \u043f\u043e\u0440\u043e\u0433\u0430 \u043d\u0435\u0440\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, > 6.0). \u0421\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u00ab\u0432\u044b\u0431\u0440\u043e\u0441\u043e\u043c\u00bb.\n\n**\u0427\u0430\u0441\u0442\u043e\u0442\u0430 \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0439 (primary):** \u0434\u043e\u043b\u044f \u0432\u0430\u043b\u0438\u0434\u043d\u043e-\u0441\u043f\u0430\u0440\u0441\u0435\u043d\u043d\u044b\u0445 \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u0432 \u0432\u044b\u0431\u043e\u0440\u043a\u0435, \u043f\u043e\u043f\u0430\u0432\u0448\u0438\u0445 \u0445\u043e\u0442\u044f \u0431\u044b \u0432 \u043e\u0434\u043d\u0443 \u0438\u0437 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0439 2/3 (\u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f 1 \u2014 \u043d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0435, \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043a\u0430\u043a \u00abinvalid rate\u00bb). \u042d\u0442\u043e \u0436\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0432 \u0440\u0435\u0448\u0430\u044e\u0449\u0435\u043c \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438.\n\n**\u042d\u0442\u0430\u043b\u043e\u043d \u00ab\u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f\u00bb (\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435):** \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u2014 \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, 10k\u2013100k SMILES \u0438\u0437 ChEMBL (\u0438\u043b\u0438 DrugBank/Enamine REAL, \u0435\u0441\u043b\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0435\u0435). \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0434\u043b\u044f: (i) \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0438 3 \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0439, (ii) \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043d\u043e\u0439 \u043d\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u043a\u0438 reward, (iii) MMD/\u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u0439 \u00ab\u0441\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u043a \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c\u0443 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044e\u00bb. \u0424\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0440\u0430\u0437 \u0438 \u043d\u0430\u0432\u0441\u0435\u0433\u0434\u0430 (\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043c\u0435\u0436\u0434\u0443 \u043f\u0440\u043e\u0433\u043e\u043d\u0430\u043c\u0438), \u0432 \u043c\u0430\u043d\u0438\u0444\u0435\u0441\u0442\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f hash \u043d\u0430\u0431\u043e\u0440\u0430.\n\n## 5. \u041c\u0435\u0442\u0440\u0438\u043a\u0438\n\n**\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439:** \u0447\u0430\u0441\u0442\u043e\u0442\u0430 \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0439 (\u043f\u043e \u043f.4) \u043d\u0430 \u0432\u044b\u0431\u043e\u0440\u043a\u0435 N \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u0437\u0430 \u043f\u0440\u043e\u0433\u043e\u043d.\n\n**\u0412\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0435:**\n- *\u0421\u0432\u043e\u0439\u0441\u0442\u0432\u0430:* \u0441\u0440\u0435\u0434\u043d\u0435\u0435/\u043c\u0435\u0434\u0438\u0430\u043d\u0430 QED, p-logP, \u0434\u043e\u043b\u044f \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u0432 \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u044f\u0447\u0435\u0439\u043a\u0435 p-logP, \u0434\u043e\u043b\u044f \u0441 QED \u2265 0.5, (\u043e\u043f\u0446.) \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u0439 binding affinity \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u043f\u0440\u0435\u0434\u0438\u043a\u0442\u043e\u0440\u0430.\n- *\u0420\u0430\u0437\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u0438\u0435:* \u0447\u0438\u0441\u043b\u043e \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0445 Bemis\u2013Murcko scaffold'\u043e\u0432 \u0438 \u0438\u0445 \u0434\u043e\u043b\u044f, internal diversity = \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u043f\u043e\u043f\u0430\u0440\u043d\u043e\u0435 (1 \u2212 Tanimoto) \u043f\u043e ECFP4, \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043f\u043e\u043f\u0430\u0440\u043d\u044b\u0445 Tanimoto, \u0434\u043e\u043b\u044f \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0445 \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0445 SMILES.\n- *\u0421\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u043a \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c\u0443 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044e:* \u0434\u043e\u043b\u044f \u0443\u043b\u044c\u0442\u0440\u0430-\u0434\u043b\u0438\u043d\u043d\u044b\u0445 \u0446\u0435\u043f\u0435\u0439 (\u0442\u0430 \u0436\u0435 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f 2 \u2014 \u043c\u0430\u0440\u043a\u0435\u0440 \u0438\u0437 \u0432\u043e\u043f\u0440\u043e\u0441\u0430), \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0434\u043b\u0438\u043d\u044b SMILES/\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u043e\u0439 \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438, **MMD** (RBF-\u044f\u0434\u0440\u043e, \u043f\u043e\u0434\u0431\u043e\u0440 \u0448\u0438\u0440\u0438\u043d\u044b \u043f\u043e \u043c\u0435\u0434\u0438\u0430\u043d\u043d\u043e\u0439 \u044d\u0432\u0440\u0438\u0441\u0442\u0438\u043a\u0435) \u043f\u043e \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u043c RDKit-\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u0430\u043c \u043f\u0440\u043e\u0442\u0438\u0432 \u044d\u0442\u0430\u043b\u043e\u043d\u0430; \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e KL/JS \u043c\u0435\u0436\u0434\u0443 \u0433\u0438\u0441\u0442\u043e\u0433\u0440\u0430\u043c\u043c\u0430\u043c\u0438 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u0430 \u00ab\u0434\u043b\u0438\u043d\u0430 \u0446\u0435\u043f\u0438\u00bb.\n\n## 6. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0438 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430\n\n**6.1 \u0411\u043b\u043e\u043a-\u0441\u0445\u0435\u043c\u0430 \u0430\u043d\u0430\u043b\u0438\u0437\u0430:** \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u0439 \u0438\u0437 M \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u0435\u0439 \u2192 \u0442\u043e\u0447\u0435\u0447\u043d\u044b\u0435 \u043e\u0446\u0435\u043d\u043a\u0438 \u0432\u0441\u0435\u0445 \u043c\u0435\u0442\u0440\u0438\u043a \u0434\u043b\u044f A \u0438 B (\u0438 C). \u0414\u0430\u043b\u0435\u0435:\n- **\u0414\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u044b:** \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f 10 000 \u0440\u0435\u0441\u0435\u043c\u043f\u043b\u043e\u0432 \u043f\u043e \u0432\u044b\u0431\u043e\u0440\u043a\u0430\u043c \u043c\u043e\u043b\u0435\u043a\u0443\u043b (\u043f\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430\u043c \u2014 \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f \u0434\u043b\u044f \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0441\u0442\u0438) \u2192 95% CI \u043d\u0430 \u043a\u0430\u0436\u0434\u0443\u044e \u043c\u0435\u0442\u0440\u0438\u043a\u0443 \u0432 \u043a\u0430\u0436\u0434\u043e\u0439 \u0432\u0435\u0442\u043a\u0435.\n- **\u0422\u0435\u0441\u0442 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u044f:** permutation-\u0442\u0435\u0441\u0442 \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u0438 \u0441\u0440\u0435\u0434\u043d\u0438\u0445 (10 000 \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u043e\u0432\u043e\u043a \u043c\u0435\u0442\u043e\u043a A/B), p-value \u043d\u0430 \u043a\u0430\u0436\u0434\u044b\u0439 \u0438\u0441\u0445\u043e\u0434. \u0414\u043b\u044f MMD \u2014 \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u044c \u0442\u0430\u043a\u0436\u0435 \u0447\u0435\u0440\u0435\u0437 permutation-\u0442\u0435\u0441\u0442.\n- **\u041f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 \u043d\u0430 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c:** Bonferroni (\u0441\u0442\u0440\u043e\u0433\u0438\u0439) \u0438 Holm (\u043e\u0442\u0447\u0451\u0442) \u043f\u043e \u0447\u0438\u0441\u043b\u0443 \u0442\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u043c\u044b\u0445 \u0438\u0441\u0445\u043e\u0434\u043e\u0432 (\u043f\u0440\u0438 ~8\u201310 \u0438\u0441\u0445\u043e\u0434\u0430\u0445); \u0432\u0441\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u2014 \u043d\u0430 \u0441\u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 p.\n\n**6.2 \u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0440\u0435\u0448\u0435\u043d\u0438\u044f (\u043b\u043e\u043a-\u0438\u043d).** \u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u00abfeedback \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442\u00bb \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f, \u0435\u0441\u043b\u0438 \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e:\n(i) \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u0438\u0441\u0445\u043e\u0434 (\u0447\u0430\u0441\u0442\u043e\u0442\u0430 \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0439) \u0432 B \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u043d\u0438\u0436\u0435, \u0447\u0435\u043c \u0432 A: \u0441\u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 p < 0.05, \u0418 \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u043e\u0435 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u2265 \u03b4_eff = 5 \u043f.\u043f. (5 \u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043d\u044b\u0445 \u043f\u0443\u043d\u043a\u0442\u043e\u0432; \u044d\u0444\u0444\u0435\u043a\u0442 < \u03b4_eff \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043d\u0435\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c, decision criterion \u2014 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c, \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u044c);\n(ii) \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0441\u0432\u043e\u0439\u0441\u0442\u0432 \u043d\u0435 \u0443\u0445\u0443\u0434\u0448\u0430\u044e\u0442\u0441\u044f \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u043d\u0438\u0436\u0435 \u043f\u043e\u0440\u043e\u0433\u0430 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0441\u0440\u0435\u0434\u043d\u0438\u0439 QED \u0432 B \u2265 \u0432 A \u2212 0.05, \u0438\u043b\u0438 \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u0432\u044b\u0448\u0435);\n(iii) \u0440\u0430\u0437\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u0438\u0435 \u043d\u0435 \u0440\u0430\u0437\u0440\u0443\u0448\u0435\u043d\u043e: scaffold diversity/internal diversity \u0432 B \u043d\u0435 \u043f\u0430\u0434\u0430\u044e\u0442 \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u043d\u0438\u0436\u0435 A \u2212 10% \u043e\u0442\u043d. (\u0438\u043d\u0430\u0447\u0435 \u00ab\u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u0435 \u0446\u0435\u043d\u043e\u0439 \u0432\u044b\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f\u00bb \u2014 \u0442\u043e\u0436\u0435 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441, \u043d\u043e \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u0443\u0435\u043c \u043a\u0430\u043a \u043d\u0435\u0433\u0430\u0442\u0438\u0432);\n(iv) MMD \u043a \u044d\u0442\u0430\u043b\u043e\u043d\u0443 \u0432 B \u2264 \u0432 A (feedback \u043d\u0435 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0441\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u043e\u0442 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f).\n\u041d\u0435\u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043b\u044e\u0431\u043e\u0433\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u2192 \u00abfeedback \u043d\u0435 \u0443\u043b\u0443\u0447\u0448\u0430\u0435\u0442 \u043f\u043e \u0434\u0430\u043d\u043d\u043e\u0439 \u043e\u0441\u0438\u00bb \u2014 \u044d\u0442\u043e \u0447\u0435\u0441\u0442\u043d\u044b\u0439 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442, \u0442\u043e\u0436\u0435 \u043e\u0442\u0432\u0435\u0442.\n\n**6.3 Robustness / sensitivity (\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f):**\n- \u041f\u043e\u0440\u043e\u0433 L* (\u0441\u0432\u0435\u0440\u0445\u0434\u043b\u0438\u043d\u043d\u044b\u0435 \u0446\u0435\u043f\u0438): \u043f\u0440\u043e\u0433\u043e\u043d \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0430 L* \u2208 {15, 20, 25, 30}; \u0432\u044b\u0432\u043e\u0434 \u043d\u0435 \u0434\u043e\u043b\u0436\u0435\u043d \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0442\u044c\u0441\u044f (\u043c\u043e\u043d\u043e\u0442\u043e\u043d\u043d\u043e\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u044b A vs B).\n- \u0412\u0435\u0441\u0430 reward (\u03bb1/\u03bb2, w2) \u0438 \u03c3: \u0440\u0435-\u0430\u043d\u0430\u043b\u0438\u0437 \u043f\u0440\u0438 \u03bb-\u0440\u0430\u0437\u0432\u0451\u0440\u0442\u043a\u0435; \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e \u044d\u0444\u0444\u0435\u043a\u0442 \u043d\u0435 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0439 \u0432\u0435\u0441\u043e\u0432\u043a\u0438.\n- \u0422\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u0430 \u0441\u044d\u043c\u043f\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f: T \u2208 {0.8, 1.0, 1.2}.\n- \u041d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f/\u043d\u043e\u0440\u043c\u0430 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 \u0434\u043b\u044f MMD: \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u044c \u0441 \u0434\u0440\u0443\u0433\u0438\u043c \u043d\u0430\u0431\u043e\u0440\u043e\u043c \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 (ECFP-based \u0432\u0435\u043a\u0442\u043e\u0440 \u0432\u043c\u0435\u0441\u0442\u043e \u043c\u043e\u0440\u0433\u043e\u043d\u043e\u0432\u0441\u043a\u0438\u0445 RDKit-\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432), \u0447\u0442\u043e\u0431\u044b \u0432\u044b\u0432\u043e\u0434 \u043f\u043e \u00ab\u0441\u043c\u0435\u0449\u0435\u043d\u0438\u044e\u00bb \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u0435\u043b \u043e\u0442 \u043e\u0434\u043d\u043e\u0433\u043e \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f.\n- \u041e\u0446\u0435\u043d\u043a\u0430 \u00ab\u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u0435\u043d\u00bb: \u0435\u0441\u043b\u0438 \u0432\u044b\u0432\u043e\u0434 \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u043a\u0440\u0430\u044f\u0445 \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u043e\u0432 \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044c.\n\n## 7. \u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u0438 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u0447\u0451\u0442\u043a\u043e \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u043d\u044b\u0435)\n\n**\u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u0434\u0438\u0437\u0430\u0439\u043d\u0430 (\u0447\u0442\u043e \u043d\u0435 \u0434\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u043c):**\n- \u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0432\u0435\u0442\u043e\u043a \u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u043e\u0435/\u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u043d\u043e\u0435; \u043d\u0435 \u0434\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c (\u0447\u0442\u043e \u0438\u043c\u0435\u043d\u043d\u043e reward-\u0442\u0435\u0440\u043c \u0432\u044b\u0437\u044b\u0432\u0430\u0435\u0442 \u044d\u0444\u0444\u0435\u043a\u0442) \u2014 \u0434\u043b\u044f \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u0430 \u043d\u0443\u0436\u043d\u0430 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u0430\u0431\u043b\u044f\u0446\u0438\u044f \u043f\u043e \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430\u043c reward (\u0432 \u0440\u0430\u043c\u043a\u0430\u0445 C/\u0434\u043e\u043f. \u0430\u0431\u043b\u044f\u0446\u0438\u0438).\n- \u00ab\u0413\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u044f\u00bb \u2014 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435, \u0430 \u043d\u0435 \u0437\u043e\u043b\u043e\u0442\u043e\u0439 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442; \u0440\u0430\u0437\u043d\u044b\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u043c\u043e\u0433\u0443\u0442 \u043c\u0435\u043d\u044f\u0442\u044c \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u044b\u0435 \u0447\u0430\u0441\u0442\u043e\u0442\u044b (\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 A vs B \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0441\u0442\u044c).\n- \u042d\u0442\u0430\u043b\u043e\u043d \u00ab\u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f\u00bb \u2014 \u0432\u044b\u0431\u043e\u0440 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0433\u043e \u043a\u043e\u0440\u043f\u0443\u0441\u0430; \u043f\u0435\u0440\u0435\u043d\u043e\u0441 \u043d\u0430 \u0434\u0440\u0443\u0433\u0438\u0435 \u043a\u043e\u0440\u043f\u0443\u0441\u0430 \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f.\n- \u042d\u0444\u0444\u0435\u043a\u0442 seed/\u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u044f\u043c\u0438 \u043f\u043e seed; \u043f\u0435\u0440\u0435\u043d\u043e\u0441 \u043d\u0430 \u0434\u0440\u0443\u0433\u0443\u044e \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0443 \u2014 \u0432\u043d\u0435 \u0434\u0438\u0437\u0430\u0439\u043d\u0430.\n\n**\u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u0432\u044b\u0431\u043e\u0440\u044b \u0434\u0438\u0437\u0430\u0439\u043d\u0430, \u043d\u0435 \u0444\u0430\u043a\u0442\u044b \u0432\u0445\u043e\u0434\u0430):**\n- \u0411\u0430\u0437\u043e\u0432\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c: SMILES-RNN/\u0442\u0440\u0430\u043d\u0441\u0444\u043e\u0440\u043c\u0435\u0440 (\u0432\u0445\u043e\u0434 \u044d\u0442\u043e\u0433\u043e \u043d\u0435 \u0437\u0430\u0434\u0430\u0451\u0442).\n- \u0424\u043e\u0440\u043c\u0430 feedback: reward-based RL (REINVENT-style), classifier-guided \u2014 \u0430\u0431\u043b\u044f\u0446\u0438\u044f.\n- \u042d\u0442\u0430\u043b\u043e\u043d \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f: ChEMBL/DrugBank-\u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0430 10k\u2013100k.\n- p-logP/QED: \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0435 RDKit-\u0440\u0430\u0441\u0447\u0451\u0442\u044b; binding affinity \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u043f\u0440\u0435\u0434\u0438\u043a\u0442\u043e\u0440\u0430 (\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u0443\u043a\u0430\u0432).\n- \u041f\u043e\u0440\u043e\u0433\u0438 (L*=20, \u03b4_eff=5 \u043f.\u043f., SAScore>6.0, QED\u22650.5, p-logP\u2208[1,4]) \u2014 \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u044b\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f, \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0442\u0441\u044f sensitivity.\n- \u041f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u0438 M=8, \u03b1=0.05, \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f 10 000, Bonferroni/Holm.\n\n**\u041d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438:** \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0441\u0442\u044c \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0439; \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c MMD \u043a \u044f\u0434\u0440\u0443/\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u0430\u043c; \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044c \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u043e\u0442 seed/\u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b; \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c \u0438 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u043f\u0440\u0435\u0434\u0438\u043a\u0442\u043e\u0440\u0430 binding affinity; \u043e\u0431\u044a\u0451\u043c \u0440\u0443\u043a\u0430\u0432\u0430 C (\u0431\u044e\u0434\u0436\u0435\u0442 CPU).\n\n## 8. \u041e\u0446\u0435\u043d\u043a\u0430 \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u043e\u0441\u0442\u0438 (\u0447\u0442\u043e \u043d\u0443\u0436\u043d\u043e \u043f\u0440\u0438 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c \u0437\u0430\u043f\u0443\u0441\u043a\u0435)\n\n- **\u0414\u0430\u043d\u043d\u044b\u0435 (\u043a\u043e\u0440\u043f\u0443\u0441):** 10k\u2013100k \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 SMILES (ChEMBL/DrugBank); \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f hash \u043d\u0430\u0431\u043e\u0440\u0430.\n- **\u0411\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0438:** RDKit (\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b, Tanimoto, scaffold'\u044b, p-logP/QED), PyTorch (\u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 \u0438 RL-\u0444\u0438\u043d\u0442\u044e\u043d), numpy/scipy (\u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f/permutation/MMD), scikit-learn (\u0434\u043b\u044f \u0440\u0443\u043a\u0430\u0432\u0430 C-\u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440\u0430) \u2014 \u0441\u0435\u0439\u0447\u0430\u0441 **\u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442**, \u0441\u0440\u0435\u0434\u0430 system-python, \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430 \u2192 \u043f\u0435\u0440\u0435\u0434 \u0437\u0430\u043f\u0443\u0441\u043a\u043e\u043c \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u0438\u0437 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043a\u044d\u0448\u0430/source (\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 \u043e \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438).\n- **\u0412\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e, CPU-only \u0432\u0430\u0440\u0438\u0430\u043d\u0442:** \u043c\u0430\u043b\u044b\u0439 SMILES-RNN (~2 \u0441\u043b\u043e\u044f GRU, hidden 512) \u043d\u0430 ~50k \u0441\u0442\u0440\u043e\u043a \u043e\u0431\u0443\u0447\u0430\u0435\u0442\u0441\u044f \u0437\u0430 ~1\u20132 \u0447\u0430\u0441\u0430 \u043d\u0430 224 CPU; RL-\u0444\u0438\u043d\u0442\u044e\u043d (30\u201350 \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439 \u043f\u043e \u0431\u0430\u0442\u0447\u0430\u043c 256) \u2014 \u0435\u0449\u0451 ~2\u20134 \u0447\u0430\u0441\u0430; RDKit-\u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u043d\u0430 2\u00d710 000\u00d78 \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u2014 \u043c\u0438\u043d\u0443\u0442\u044b\u2013\u0447\u0430\u0441\u044b. \u0418\u0442\u043e\u0433\u043e \u043e\u0434\u0438\u043d \u043f\u043e\u043b\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u043e\u043d \u0441 8 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u044f\u043c\u0438 \u2248 1\u20132 \u0441\u0443\u0442\u043e\u043a CPU (\u0431\u0435\u0437 GPU). GPU \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b \u0431\u044b \u0434\u043e \u0447\u0430\u0441\u043e\u0432, \u043d\u043e \u043d\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d.\n- **Binding-affinity \u0440\u0443\u043a\u0430\u0432:** \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0443 \u044d\u0442\u0430\u043b\u043e\u043d\u0430 \u0441 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u043d\u044b\u043c\u0438/\u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u043c\u0438 \u0430\u0444\u0444\u0438\u043d\u0438\u0442\u0438 \u0438 \u043f\u0440\u0435\u0434\u0438\u043a\u0442\u043e\u0440 \u2014 \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u0434\u0430\u043d\u043d\u044b\u0445/\u043c\u043e\u0434\u0435\u043b\u0438; \u0432 \u043f\u0440\u043e\u0442\u0438\u0432\u043d\u043e\u043c \u0441\u043b\u0443\u0447\u0430\u0435 \u0440\u0443\u043a\u0430\u0432 \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u044f\u0432\u043d\u043e (\u044d\u0442\u043e \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435, \u043d\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e).\n- **\u0421\u0440\u043e\u043a\u0438 (bounded):** \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 0.5\u20131 \u0434\u0435\u043d\u044c, \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435+\u0444\u0438\u043d\u0442\u044e\u043d+\u043c\u0435\u0442\u0440\u0438\u043a\u0438 1\u20132 \u0434\u043d\u044f CPU, \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u0438 sensitivity 0.5\u20131 \u0434\u0435\u043d\u044c; \u0438\u0442\u043e\u0433\u043e ~3\u20134 \u0434\u043d\u044f \u0440\u0430\u0431\u043e\u0447\u0435\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u043e\u043d.", "evidence": "\u041e\u0441\u043c\u043e\u0442\u0440 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d \u043a\u043e\u043c\u0430\u043d\u0434\u0430\u043c\u0438: /workspace \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json (794 B); find / \u043f\u043e track.md/readme/*.smi/*.sdf/*.csv/*.npz/*.pth/*.pt/*.ckpt \u2014 \u043f\u0443\u0441\u0442\u043e; task.json \u2192 documents.track